-- Google Maps ingest (ticket T16): lists, places identity, enrichment state.
--
-- T2 created `lists` and `places` empty; nothing wrote them until T16. Three
-- gaps had to close before an import could be idempotent:
--
--   * a place had no stable identity, so "the same file twice" could only be
--     handled by reading first and writing second — a race, and the exact
--     read-then-write the ticket forbids. `place_key` is generated by Postgres
--     from the columns that define identity (Google's `place_id` when we have
--     it, otherwise the coordinates rounded to ~1 m plus the normalized name),
--     so the unique index below is the only thing enforcing dedupe: two
--     concurrent uploads of the same file cannot both insert.
--   * `enrichment` records *why* a row has no coordinates. A row with a blank
--     address is not an error and is not dropped: it is stored `unresolved` and
--     stays visible, so an import can never silently lose a place.
--   * `enriched_at` alone cannot express "we tried and found nothing".
--
-- `created_at` on both tables is ordering only: `GET /api/v1/lists` is
-- newest-first and `GET /api/v1/lists/{id}/places` follows import order.

ALTER TABLE lists ADD COLUMN created_at TIMESTAMPTZ NOT NULL DEFAULT now();

-- One list per (file name, source): re-uploading the same Takeout file finds
-- the list it made last time instead of making a second one.
CREATE UNIQUE INDEX lists_user_id_name_source_key ON lists (user_id, name, source);

ALTER TABLE places
    ADD COLUMN place_key TEXT GENERATED ALWAYS AS (
        CASE
            WHEN place_id IS NOT NULL AND btrim(place_id) <> '' THEN
                'pid:' || btrim(place_id)
            ELSE
                'geo:'
                || coalesce(round(lat::numeric, 5)::text, '')
                || ','
                || coalesce(round(lng::numeric, 5)::text, '')
                || ':'
                || lower(regexp_replace(btrim(name), '[[:space:]]+', ' ', 'g'))
        END
    ) STORED;

-- Rows written before this migration (none in practice) key off their name.
CREATE UNIQUE INDEX places_user_id_place_key_key ON places (user_id, place_key);

ALTER TABLE places
    ADD COLUMN enrichment TEXT NOT NULL DEFAULT 'pending'
        CONSTRAINT places_enrichment_check
        CHECK (enrichment IN ('pending', 'resolved', 'unresolved'));

ALTER TABLE places ADD COLUMN created_at TIMESTAMPTZ NOT NULL DEFAULT now();

CREATE INDEX places_list_id_idx ON places (list_id);
